corrected_code:
const express = require('express');
const knex = require('../db');
const { verifyAdminAuth } = require('../middleware/auth');

const router = express.Router();

router.patch('/api/maintenance/schedules/:scheduleId', verifyAdminAuth, async (req, res) => {
  const { scheduleId } = req.params;
  const { cronExpression, maintenanceWindowHours } = req.body;

  const schedule = await knex('cluster_maintenance_schedules')
    .where({ id: scheduleId, tenant_id: req.user.tenantId })
    .first();
  if (!schedule) {
    return res.status(403).json({ error: 'Forbidden: schedule does not belong to your organization' });
  }

  await knex('cluster_maintenance_schedules')
    .where({ id: scheduleId, tenant_id: req.user.tenantId })
    .update({
      cron_expression: cronExpression,
      window_hours: maintenanceWindowHours,
      updated_at: new Date()
    });

  res.json({ success: true, scheduleId });
});
